1	import { readFileSync } from "node:fs";
2	import path from "node:path";
3	import type { APIRequestContext, Browser } from "@playwright/test";
4	import { expect, test } from "@playwright/test";
5	import { firstGrammarIds, seedLearnedVocabulary } from "./fixtures/seedLearner";
6	
7	/**
8	 * End-to-end integration proof for the AI conversation practice pipeline —
9	 * task 1.4. Runs only under the `conversation-practice` Playwright project
10	 * (`npm run test:e2e -- --project=conversation-practice`), which owns its
11	 * own real backend process via the conversation-backend-setup/-teardown
12	 * dependency (see playwright.config.ts) rather than the shared `webServer`
13	 * array, so the app's existing home/lesson-intro specs never boot a GPU
14	 * backend.
15	 *
16	 * Chromium loops the fake-capture file continuously from stream start
17	 * (`--use-file-for-fake-audio-capture`), so both fixture WAVs are padded
18	 * with ~1s of leading/trailing silence — recording for 3s comfortably
19	 * captures real speech regardless of exact click timing.
20	 */
21	
22	const HEALTH_URL = "http://localhost:8000/health";
23	const BANK_JSON = path.resolve(
24		process.cwd(),
25		"backend/data/conversationStarters.json",
26	);
27	const READY_TIMEOUT_MS = 4 * 60_000;
28	const READY_POLL_INTERVAL_MS = 2_000;
29	
30	async function waitForBackendReady(request: APIRequestContext): Promise<void> {
31		const deadline = Date.now() + READY_TIMEOUT_MS;
32		let lastLoaded: Record<string, boolean> | null = null;
33		while (Date.now() < deadline) {
34			try {
35				const res = await request.get(HEALTH_URL);
36				if (res.ok()) {
37					const body = (await res.json()) as {
38						models_loaded: Record<string, boolean>;
39					};
40					lastLoaded = body.models_loaded;
41					if (Object.values(lastLoaded).every(Boolean)) return;
42				}
43			} catch {
44				// Backend not accepting connections yet — keep polling.
45			}
46			await new Promise((resolve) => setTimeout(resolve, READY_POLL_INTERVAL_MS));
47		}
48		const stalled = lastLoaded
49			? Object.entries(lastLoaded)
50					.filter(([, ready]) => !ready)
51					.map(([name]) => name)
52			: ["whisper", "judge", "tts"];
53		throw new Error(
54			`Backend did not become ready within ${READY_TIMEOUT_MS}ms — ` +
55				`stalled model(s): ${stalled.join(", ") || "unknown (no /health response yet)"}`,
56		);
57	}
58	
59	interface BankEntry {
60		tier: number;
61		thai: string;
62		words: string[];
63	}
64	
65	function bankEntries(): BankEntry[] {
66		return JSON.parse(readFileSync(BANK_JSON, "utf8")) as BankEntry[];
67	}
68	
69	/**
70	 * One learner's whole opening exchange: seed their progress, open
71	 * `/conversation`, and read back the question the real backend picked from
72	 * the real bank for them.
73	 */
74	async function askOpeningQuestion(
75		browser: Browser,
76		learnedWordCount: number,
77	): Promise<{ knownWords: string[]; questionText: string }> {
78		const context = await browser.newContext({
79			baseURL: test.info().project.use.baseURL,
80		});
81		try {
82			const page = await context.newPage();
83			// Phase 3's gate (task 3.2) requires both a vocab AND a grammar count —
84			// every fixture reaching `/conversation` needs both now, not just the
85			// vocab count this helper originally seeded.
86			const knownWords = await seedLearnedVocabulary(
87				page,
88				learnedWordCount,
89				7,
90				firstGrammarIds(5),
91			);
92			await page.goto("/thai-script/#/conversation");
93			const question = page.locator('p[lang="th"]');
94			await expect(question).toBeVisible({ timeout: 60_000 });
95			return { knownWords, questionText: (await question.innerText()).trim() };
96		} finally {
97			await context.close();
98		}
99	}
100	
101	test.describe("conversation practice — real backend, acceptable reply", () => {
102		test.beforeAll(async ({ request }) => {
103			await waitForBackendReady(request);
104		});
105	
106		test("a fake-mic pass reply drives a real pass verdict (AC2)", async ({
107			page,
108		}) => {
109			// Seeded rather than run against an empty profile: the question is
110			// now drawn from the bank by what this learner knows, and the
111			// fake-mic fixture answers a "how are you" opener — which is what a
112			// 220-word learner is asked. (Phase 1 could hardcode the question;
113			// from here on the content is personalized, so the fixture and the
114			// seeded learner have to belong together.)
115			await seedLearnedVocabulary(page, 220, 7, firstGrammarIds(5));
116			await page.goto("/thai-script/#/conversation");
117			const question = page.locator('p[lang="th"]');
118			await expect(question).toBeVisible({ timeout: 30_000 });
119			expect((await question.innerText()).trim().length).toBeGreaterThan(0);
120	
121			await page.getByRole("button", { name: "Record your reply" }).click();
122			await page.waitForTimeout(3_000);
123			await page.getByRole("button", { name: "Stop recording" }).click();
124	
125			// Transcript non-empty BEFORE the verdict — a capture-timing miss must
126			// report as "nothing was heard", never as a false "the judge said fail".
127			await expect(page.getByText("We heard:")).toBeVisible({ timeout: 30_000 });
128			const transcript = await page.locator('span[lang="th"]').textContent();
129			expect(transcript?.trim().length ?? 0).toBeGreaterThan(0);
130	
131			await expect(page.getByText("Good answer")).toBeVisible({
132				timeout: 60_000,
133			});
134		});
135	});
136	
137	// The off-topic-reply case (AC3) needs a different
138	// `--use-file-for-fake-audio-capture` value, which Playwright only allows
139	// via a file-top-level `test.use()` (a describe-scoped override "forces a
140	// new worker" and is refused) — see conversation-practice-fail.spec.ts.
141	
142	test.describe("conversation practice — backend unreachable", () => {
143		test("a simulated connection failure renders the not-running state without hanging (AC4)", async ({
144			page,
145		}) => {
146			// Seeded above the phase-3 gate first: an unseeded learner would see
147			// the locked page before ever attempting a backend call, which would
148			// make this assertion pass for the wrong reason.
149			await seedLearnedVocabulary(page, 220, 7, firstGrammarIds(5));
150			// No process is stopped and task 1.3's frozen base-URL constant is
151			// never repointed — this produces exactly the `fetch` rejection the
152			// adapter's `unavailable` path is already built to handle.
153			await page.route("**/localhost:8000/**", (route) =>
154				route.abort("connectionrefused"),
155			);
156			await page.goto("/thai-script/#/conversation");
157			await expect(page.getByRole("alert")).toContainText("not running", {
158				timeout: 15_000,
159			});
160		});
161	});
162	
163	// AC5: a person actually listens to the opening question's synthesized audio
164	// and confirms it's audible, intelligible Thai in the cloned voice. No
165	// automated test can judge audio quality — see this task's manual
166	// verification note.
167	
168	// The seeding helper itself, proven on its own before anything below leans
169	// on it: a silently-wrong localStorage DTO shape would otherwise produce an
170	// empty learner that still passes every assertion about "two different
171	// questions" for entirely the wrong reason. Deliberately outside the
172	// backend-dependent describe below — what the app makes of seeded progress
173	// is not a question about the conversation backend.
174	test.describe("seeded learner state", () => {
175		test("seedLearnedVocabulary produces a learner the app really sees", async ({
176			page,
177		}) => {
178			const knownWords = await seedLearnedVocabulary(page, 150);
179			expect(knownWords).toHaveLength(150);
180	
181			await page.goto("/thai-script/#/");
182	
183			// One due vocabulary card per seeded word, counted by the app's own
184			// SRS state — not by reading back what the helper just wrote.
185			await expect(page.getByRole("button", { name: "Vocab (150)" })).toBeVisible(
186				{ timeout: 30_000 },
187			);
188		});
189	});
190	
191	test.describe("conversation practice — a real multi-turn session (task 3.3 AC5)", () => {
192		test.beforeAll(async ({ request }) => {
193			await waitForBackendReady(request);
194		});
195	
196		test("completes three real turns end to end against the real backend and bank, with a summary naming the total", async ({
197			page,
198		}) => {
199			// This spec's own locked-path proof was retired (task 3.2 owns it
200			// now, in e2e/conversation-gate.spec.ts) — this test only proves the
201			// multi-turn session mechanic for an already-unlocked learner.
202			//
203			// gapEvery=15, not the default 7: checked directly against the real
204			// shipped bank, a 1-in-7 gappy set only ever qualifies for 2 of tier
205			// 5's 8 entries at ANY word count up to 600 (common short-sentence
206			// function words keep landing on a gap position) — a real, if
207			// narrow, edge in task 2.2/2.3's entry-level containment design,
208			// not a bug in this test. A wider gap avoids it and reaches all 8
209			// qualifying entries, giving headroom for three non-repeating turns.
210			await seedLearnedVocabulary(page, 250, 15, firstGrammarIds(5));
211			await page.goto("/thai-script/#/conversation");
212	
213			for (let turn = 1; turn <= 3; turn++) {
214				const question = page.locator('p[lang="th"]');
215				await expect(question).toBeVisible({ timeout: 60_000 });
216				const questionText = (await question.innerText()).trim();
217				expect(questionText.length).toBeGreaterThan(0);
218	
219				await page.getByRole("button", { name: "Record your reply" }).click();
220				await page.waitForTimeout(3_000);
221				await page.getByRole("button", { name: "Stop recording" }).click();
222	
223				// Transcript non-empty BEFORE the verdict, same discipline AC2
224				// established — a capture-timing miss must report as "nothing
225				// was heard", never as a false verdict.
226				await expect(page.getByText("We heard:")).toBeVisible({
227					timeout: 30_000,
228				});
229				const transcript = await page.locator('span[lang="th"]').textContent();
230				expect(transcript?.trim().length ?? 0).toBeGreaterThan(0);
231	
232				if (turn < 3) {
233					// AC1: automatically advances to a genuinely different
234					// question, with no manual step and no full page reload.
235					await page.waitForFunction(
236						(prevText) =>
237							document.querySelector('p[lang="th"]')?.textContent?.trim() !==
238							prevText,
239						questionText,
240						{ timeout: 60_000 },
241					);
242				}
243			}
244	
245			// Real judge verdicts vary by question and reply content, so this
246			// proves the mechanic (three real record -> judge -> next cycles,
247			// tallied correctly) rather than a specific pass count — the tally
248			// names all three components (AC1) and totals exactly 3 asked.
249			await expect(page.getByText(/\d+ passed \/ 3 asked/)).toBeVisible({
250				timeout: 30_000,
251			});
252		});
253	});
254	
255	test.describe("conversation practice — personalized by known vocabulary (AC4)", () => {
256		test.beforeAll(async ({ request }) => {
257			await waitForBackendReady(request);
258		});
259	
260		test("two learners with different vocabulary get different questions", async ({
261			browser,
262		}) => {
263			// 220 and 250, not 150 and 400: task 3.2's gate requires
264			// >= MIN_VOCAB_COUNT (200) words before /conversation is reachable at
265			// all, ruling out 150. Selection is entry-level containment with a
266			// hash-based tie-break among qualifying entries (task 2.3), which is
267			// not monotonic in word count — a larger gappy word set does not
268			// always unlock a different entry (220 and 400 land on the same one
269			// against the real shipped bank). 220 and 250 are confirmed, against
270			// that same real bank, to select two different entries.
271			const beginner = await askOpeningQuestion(browser, 220);
272			const advanced = await askOpeningQuestion(browser, 250);
273	
274			expect(beginner.questionText).not.toEqual(advanced.questionText);
275	
276			// And each question is one that learner could actually understand:
277			// every word in it is a word they know.
278			const entries = bankEntries();
279			for (const learner of [beginner, advanced]) {
280				const entry = entries.find((e) => e.thai === learner.questionText);
281				expect(
282					entry,
283					`"${learner.questionText}" is not an entry in the shipped bank`,
284				).toBeDefined();
285				const known = new Set(learner.knownWords);
286				expect(
287					(entry as BankEntry).words.filter((word) => !known.has(word)),
288				).toEqual([]);
289			}
290		});
291	});
292

